import React, { createContext, useContext, useState, useCallback, useEffect } from 'react';
import { IShape, ToolType, IPoint, TransformMode } from '../types';
import { DEFAULT_HEIGHT, DEFAULT_COLOR } from '../constants';

type UnitType = 'm' | 'cm';

interface AppContextType {
  shapes: IShape[];
  addShape: (shape: IShape) => void;
  updateShape: (id: string, updates: Partial<IShape>) => void;
  removeShape: (id: string) => void;
  copyShape: (id: string) => void;
  selectedId: string | null;
  setSelectedId: (id: string | null) => void;
  tool: ToolType;
  setTool: (tool: ToolType) => void;
  transformMode: TransformMode;
  setTransformMode: (mode: TransformMode) => void;
  clearScene: () => void;
  addAIShapes: (items: any[]) => void;
  unit: UnitType;
  setUnit: (unit: UnitType) => void;
  formatValue: (val: number) => string;
  undo: () => void;
  redo: () => void;
  canUndo: boolean;
  canRedo: boolean;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // History State
  const [history, setHistory] = useState<IShape[][]>([[]]);
  const [historyIndex, setHistoryIndex] = useState(0);

  const [shapes, setShapes] = useState<IShape[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [transformMode, setTransformMode] = useState<TransformMode>('translate');
  const [unit, setUnit] = useState<UnitType>('m');

  // Internal helper to commit changes to history
  const _commitShapes = (newShapes: IShape[]) => {
    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(newShapes);
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
    setShapes(newShapes);
  };

  const undo = useCallback(() => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setShapes(history[newIndex]);
    }
  }, [history, historyIndex]);

  const redo = useCallback(() => {
    if (historyIndex < history.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setShapes(history[newIndex]);
    }
  }, [history, historyIndex]);

  const addShape = useCallback((shape: IShape) => {
    const newShapes = [...shapes, shape];
    _commitShapes(newShapes);
    if (shape.id) setSelectedId(shape.id);
  }, [shapes, historyIndex, history]);

  const updateShape = useCallback((id: string, updates: Partial<IShape>) => {
    const newShapes = shapes.map(s => s.id === id ? { ...s, ...updates } : s);
    _commitShapes(newShapes);
  }, [shapes, historyIndex, history]);

  const removeShape = useCallback((id: string) => {
    const newShapes = shapes.filter(s => s.id !== id);
    _commitShapes(newShapes);
    if (selectedId === id) setSelectedId(null);
  }, [shapes, selectedId, historyIndex, history]);

  const copyShape = useCallback((id: string) => {
    const target = shapes.find(s => s.id === id);
    if (!target) return;

    const newShape: IShape = {
      ...target,
      id: `copy-${Date.now()}`,
      name: `${target.name} (複製)`,
      position: [target.position[0] + 1, target.position[1], target.position[2] + 1]
    };

    const newShapes = [...shapes, newShape];
    _commitShapes(newShapes);
  }, [shapes, historyIndex, history]);

  const clearScene = useCallback(() => {
    _commitShapes([]);
    setSelectedId(null);
  }, [historyIndex, history]);

  const addAIShapes = useCallback((items: any[]) => {
    const newGeneratedShapes: IShape[] = items.map((item, index) => {
      const w = item.width / 2;
      const d = item.depth / 2;
      const points: IPoint[] = [
        { x: -w, y: 0, z: -d },
        { x: w, y: 0, z: -d },
        { x: w, y: 0, z: d },
        { x: -w, y: 0, z: d },
        { x: -w, y: 0, z: -d },
      ];

      return {
        id: `ai-${Date.now()}-${index}`,
        type: 'solid',
        name: item.name,
        points,
        height: item.height,
        color: item.color || DEFAULT_COLOR,
        position: [item.x, 0, item.z],
        rotation: 0,
        scale: [1, 1, 1]
      };
    });

    const newShapes = [...shapes, ...newGeneratedShapes];
    _commitShapes(newShapes);
  }, [shapes, historyIndex, history]);

  const formatValue = useCallback((val: number) => {
    if (unit === 'cm') {
      return `${(val * 100).toFixed(0)} 公分`;
    }
    return `${val.toFixed(2)} 公尺`;
  }, [unit]);

  return (
    <AppContext.Provider value={{
      shapes,
      addShape,
      updateShape,
      removeShape,
      copyShape,
      selectedId,
      setSelectedId,
      tool,
      setTool,
      transformMode,
      setTransformMode,
      clearScene,
      addAIShapes,
      unit,
      setUnit,
      formatValue,
      undo,
      redo,
      canUndo: historyIndex > 0,
      canRedo: historyIndex < history.length - 1
    }}>
      {children}
    </AppContext.Provider>
  );
};

