const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();

    useEffect(() => {
        if (!view) return;

        const ctrl = controls as unknown as OrbitControlsImpl;
        if (!ctrl) return;

        // Use current distance to target to maintain scale roughly
        const currentTarget = ctrl.target.clone();
        const dist = camera.position.distanceTo(currentTarget) || 10;

        // Small offset to prevent Gimbal lock on Top/Bottom views with default up (0,1,0)
        const offset = 0.001; 

        switch (view) {
            case '上視圖': // Top View
                camera.position.set(currentTarget.x, currentTarget.y + dist, currentTarget.z + offset);
                break;
            case '下視圖': // Bottom View
                camera.position.set(currentTarget.x, currentTarget.y - dist, currentTarget.z + offset);
                break;
            case '前視圖': // Front View
                camera.position.set(currentTarget.x, currentTarget.y, currentTarget.z + dist);
                break;
            case '後視圖': // Rear View
                camera.position.set(currentTarget.x, currentTarget.y, currentTarget.z - dist);
                break;
            case '右視圖': // Right View
                camera.position.set(currentTarget.x + dist, currentTarget.y, currentTarget.z);
                break;
            case '左視圖': // Left View
                camera.position.set(currentTarget.x - dist, currentTarget.y, currentTarget.z);
                break;
        }

        ctrl.update();
        onFinished();
    }, [view, camera, controls, onFinished]);

    return null;
};


const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3 | [number, number, number]; type?: SnapType }> = ({ text, position, type }) => {
  const pos = Array.isArray(position) ? position : [position.x, 0.5, position.z];

  let bgColor = "bg-black/80";
  let ringColor = "border-white/20";

  if (type === 'vertex') { bgColor = "bg-green-600/90"; ringColor = "border-green-400"; }
  else if (type === 'midpoint') { bgColor = "bg-cyan-600/90"; ringColor = "border-cyan-400"; }
  else if (type === 'edge') { bgColor = "bg-red-600/90"; ringColor = "border-red-400"; }
  else if (type === 'align') { bgColor = "bg-purple-600/90"; ringColor = "border-purple-400"; }

  return (
    <Html position={[pos[0], 0.5, pos[2]]} center style={{ pointerEvents: 'none' }}>
      <div className={`${bgColor} text-white text-xs px-2 py-1 rounded-md whitespace-nowrap backdrop-blur-sm border ${ringColor} shadow-lg font-bold flex items-center gap-1 transition-all`}>
        {text}
      </div>
    </Html>
  );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType }> = ({ position, type }) => {
    if (type === 'none' || type === 'grid') return null;

    const color = type === 'vertex' ? '#22c55e' : type === 'midpoint' ? '#06b6d4' : type === 'edge' ? '#ef4444' : '#a855f7'; // Purple for align
    const rotationZ = type === 'midpoint' ? Math.PI / 4 : 0;

    return (
        <group position={position}>
             {/* Main Indicator Shape */}
             <mesh rotation={[-Math.PI/2, 0, rotationZ]}>
                {type === 'vertex' && <circleGeometry args={[0.08, 32]} />}
                {(type === 'midpoint' || type === 'edge') && <planeGeometry args={[0.12, 0.12]} />}
                {type === 'align' && (
                    <ringGeometry args={[0.08, 0.12, 4]} /> // Square ring
                )}
                <meshBasicMaterial color={color} depthTest={false} />
            </mesh>
            {/* Outer Pulse Ring for "Adsorption" effect */}
            {(type === 'vertex' || type === 'midpoint' || type === 'edge') && (
                 <mesh rotation={[-Math.PI/2, 0, rotationZ]}>
                    <ringGeometry args={[0.13, 0.15, 32]} />
                    <meshBasicMaterial color={color} transparent opacity={0.5} depthTest={false} />
                </mesh>
            )}
        </group>
    );
}

const PreviewFill: React.FC<{ points: IPoint[], y: number }> = ({ points, y }) => {
  const shape = useMemo(() => {
    if (!points || points.length < 3) return null;
    const s = new THREE.Shape();
    if (points[0]) {
      s.moveTo(points[0].x, -points[0].z);
      for (let i = 1; i < points.length; i++) {
        if (points[i]) {
            s.lineTo(points[i].x, -points[i].z);
        }
      }
    }
    s.closePath();
    return s;
  }, [points]);

  if (!shape) return null;

  return (
    <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, y + 0.02, 0]}>
      <shapeGeometry args={[shape]} />
      <meshBasicMaterial color="#38bdf8" transparent opacity={0.3} side={THREE.DoubleSide} depthTest={false} />
    </mesh>
  );
};

const DrawingManager: React.FC = () => {
  const { tool, addShape, replaceShapes, formatValue, shapes, wallThickness } = useApp();
  const [startPoint, setStartPoint] = useState<IPoint | null>(null);
  const [currentPoint, setCurrentPoint] = useState<IPoint | null>(null);
  const [polyPoints, setPolyPoints] = useState<IPoint[]>([]);
  const [measureStart, setMeasureStart] = useState<IPoint | null>(null);
  const [measureEnd, setMeasureEnd] = useState<IPoint | null>(null);

  // Lock for prevent double execution
  const processingRef = useRef(false);

  // Snap State
  const [snapType, setSnapType] = useState<SnapType>('none');
  const [guides, setGuides] = useState<THREE.Vector3[][]>([]);

  const { raycaster, scene, camera } = useThree();

  useEffect(() => {
    setStartPoint(null);
    setCurrentPoint(null);
    setPolyPoints([]);
    setMeasureStart(null);
    setMeasureEnd(null);
    setSnapType('none');
    setGuides([]);
    processingRef.current = false;
  }, [tool]);

  useFrame(({ pointer }) => {
    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
        if (currentPoint) setCurrentPoint(null);
        return;
    }

    raycaster.setFromCamera(pointer, camera);
    const interactables = scene.children.filter(obj => 
        obj.name === 'ground_plane'
    );
    const intersects = raycaster.intersectObjects(interactables, true);

    if (intersects.length > 0) {
        const rawPoint = intersects[0].point;

        // Include startPoint in active points for snapping back to start (e.g., drawing Rect/Circle)
        const activeSnapPoints = [...polyPoints];
        if (startPoint) activeSnapPoints.push(startPoint);

        const snapResult = getGeometrySnap(rawPoint, shapes, activeSnapPoints, SNAP_THRESHOLD);

        const x = snapResult.position.x;
        const z = snapResult.position.z;
        let y = snapResult.position.y;
        if (y < 0.05) y = 0;

        if (!currentPoint || 
            Math.abs(currentPoint.x - x) > 0.001 || 
            Math.abs(currentPoint.z - z) > 0.001 ||
            snapType !== snapResult.type) {

            setCurrentPoint({ x, y, z });
            setSnapType(snapResult.type);
            setGuides(snapResult.guides || []);
        }
    } else {
        if (currentPoint) {
            setCurrentPoint(null);
            setSnapType('none');
            setGuides([]);
        }
    }
  });

  const handleClick = (e: ThreeEvent<MouseEvent>) => {
    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || !currentPoint) return;
    e.stopPropagation(); // Stop event from bubbling up
    if (processingRef.current) return; // Prevent double firing

    const p = { ...currentPoint };

    if (tool === ToolType.MEASURE) {
        if (!measureStart) {
            setMeasureStart(p);
            setMeasureEnd(null);
        } else {
            const dist = Math.sqrt(Math.pow(p.x - measureStart.x, 2) + Math.pow(p.z - measureStart.z, 2));
            if (dist > 0.01) {
                addShape({
                    id: `dim-${Date.now()}`,
                    name: '尺寸標註',
                    type: 'dimension',
                    points: [measureStart, p], 
                    height: 0,
                    color: DIMENSION_COLOR,
                    position: [0, 0, 0],
                    rotation: 0,
                    scale: [1, 1, 1]
                });
            }
            setMeasureStart(null);
            setMeasureEnd(null);
        }
        return;
    }

    if (tool === ToolType.DRAW_POLY) {
      if (polyPoints.length > 2) {
         const start = polyPoints[0];
         const dist = Math.sqrt(Math.pow(p.x - start.x, 2) + Math.pow(p.z - start.z, 2));
         if (dist < SNAP_THRESHOLD) { 
           finishShape(polyPoints);
           return;
         }
      }
      setPolyPoints([...polyPoints, p]);
    } else {
      if (!startPoint) {
        setStartPoint(p);
      } else {
        // Only finish if distance is significant
        const dist = Math.sqrt(Math.pow(p.x - startPoint.x, 2) + Math.pow(p.z - startPoint.z, 2));
        if (dist > 0.01) {
             finishPrimitive(startPoint, p);
        }
      }
    }
  };

  const finishPrimitive = (start: IPoint, end: IPoint) => {
    if (processingRef.current) return;
    processingRef.current = true;

    let points: IPoint[] = [];
    let name = "平面";
    const cx = (start.x + end.x) / 2;
    const cz = (start.z + end.z) / 2;
    const dx = end.x - start.x;
    const dz = end.z - start.z;
    const dist = Math.sqrt(dx*dx + dz*dz);

    let finalPos: [number, number, number] = [0,0,0];

    switch (tool) {
      case ToolType.DRAW_LINE:
        const thickness = wallThickness; 
        const len = dist;
        points = [
          { x: 0, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: -thickness/2 }
        ];
        finalPos = [start.x, start.y, start.z]; 
        name = "牆面";
        break;

      case ToolType.DRAW_RECT:
        const w = Math.abs(dx);
        const d = Math.abs(dz);
        finalPos = [cx, start.y, cz];
        points = [
          { x: -w/2, y: 0, z: -d/2 },
          { x: w/2, y: 0, z: -d/2 },
          { x: w/2, y: 0, z: d/2 },
          { x: -w/2, y: 0, z: d/2 },
          { x: -w/2, y: 0, z: -d/2 }
        ];
        name = "區域";
        break;

      case ToolType.DRAW_CIRCLE:
        finalPos = [start.x, start.y, start.z];
        points = createCirclePoints(dist);
        name = "圓形";
        break;

      case ToolType.DRAW_ARC:
        finalPos = [start.x, start.y, start.z];
        points = createArcPoints(dist);
        name = "開門";
        break;
    }

    let rotation = 0;
    if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_ARC) {
       rotation = -Math.atan2(dz, dx); 
    }

    // 1. Create the new shape (The Wall / Line)
    const newWallShape: IShape = {
      id: `shape-${Date.now()}-${Math.floor(Math.random()*1000)}`,
      name: `${name}`,
      type: 'flat',
      points,
      height: DEFAULT_HEIGHT,
      color: FLAT_COLOR,
      position: finalPos,
      rotation: rotation,
      scale: [1, 1, 1]
    };

    const newShapesToAdd: IShape[] = [newWallShape];
    const idsToRemove: string[] = [];

    // 2. CUTTING LOGIC (Only when drawing lines)
    if (tool === ToolType.DRAW_LINE) {
        // Iterate over existing shapes and try to cut them
        shapes.forEach(existingShape => {
            if (existingShape.type === 'dimension') return;

            // Transform existing shape points to world space
            const worldPoints = existingShape.points.map(p => transformPoint(p, existingShape));

            // Check if this segment actually traverses the shape (intersects edges >= 2 times)
            // This prevents "Infinite Line" cuts when drawing short segments inside a shape.
            if (doesSegmentCutPolygon(worldPoints, start, end)) {
                // Define the cutting line (The drawn wall)
                // Clip against Line AB (Left Side)
                const leftPoly = clipPolygonAgainstLine(worldPoints, start, end);
                // Clip against Line BA (Right Side - technically reverse of AB)
                const rightPoly = clipPolygonAgainstLine(worldPoints, end, start);

                const originalArea = calculatePolygonArea(worldPoints);
                const leftArea = calculatePolygonArea(leftPoly);
                const rightArea = calculatePolygonArea(rightPoly);

                // If cut was successful, we should have two pieces with significant area
                if (leftArea > 0.01 && rightArea > 0.01 && leftPoly.length > 2 && rightPoly.length > 2) {
                    // The shape was cut!
                    idsToRemove.push(existingShape.id);

                    // Helper to center points for the new shape
                    const createSplitShape = (pts: IPoint[], suffix: string): IShape => {
                        const cx = pts.reduce((sum, p) => sum + p.x, 0) / pts.length;
                        const cz = pts.reduce((sum, p) => sum + p.z, 0) / pts.length;
                        // Convert world points back to local relative to new center
                        const localPoints = pts.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));
                        // Ensure closed loop
                        if (localPoints.length > 0 && (localPoints[0].x !== localPoints[localPoints.length-1].x || localPoints[0].z !== localPoints[localPoints.length-1].z)) {
                            localPoints.push(localPoints[0]);
                        }

                        return {
                            ...existingShape,
                            id: `${existingShape.id}-${suffix}`, // Preserves original ID root so we know what it came from
                            name: existingShape.name,
                            position: [cx, existingShape.position[1], cz],
                            rotation: 0, // Reset rotation as points are now world-aligned then re-centered
                            scale: [1, 1, 1],
                            points: localPoints
                        };
                    };

                    newShapesToAdd.push(createSplitShape(leftPoly, 'A'));
                    newShapesToAdd.push(createSplitShape(rightPoly, 'B'));
                }
            }
        });
    }

    // 3. Batch Update
    if (idsToRemove.length > 0) {
        replaceShapes(idsToRemove, newShapesToAdd);
    } else {
        addShape(newWallShape);
    }

    setStartPoint(null);
    // Release lock on next frame
    setTimeout(() => {
        processingRef.current = false;
    }, 100);
  };

  const finishShape = (pts: IPoint[]) => {
    if (processingRef.current) return;
    processingRef.current = true;

    if (pts.length < 3) {
        processingRef.current = false;
        return;
    }

    const cx = pts.reduce((sum, p) => sum + p.x, 0) / pts.length;
    const cz = pts.reduce((sum, p) => sum + p.z, 0) / pts.length;
    const cy = pts[0].y;

    const centeredPoints = pts.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));
    centeredPoints.push(centeredPoints[0]);

    addShape({
      id: `poly-${Date.now()}`,
      name: `多邊形`,
      type: 'flat',
      points: centeredPoints,
      height: DEFAULT_HEIGHT,
      color: FLAT_COLOR,
      position: [cx, cy, cz],
      rotation: 0,
      scale: [1, 1, 1]
    });
    setPolyPoints([]);
    setStartPoint(null);
    setTimeout(() => { processingRef.current = false; }, 100);
  };

  const previewPoints = useMemo(() => {
     if (tool === ToolType.DRAW_POLY) {
        if (polyPoints.length === 0 && !currentPoint) return [];
        const pts = [...polyPoints];
        if (currentPoint) pts.push(currentPoint);
        return pts;
     }

     if (startPoint && currentPoint) {
         if (tool === ToolType.DRAW_LINE) {
             const thickness = wallThickness; // Preview with correct thickness
             const dx = currentPoint.x - startPoint.x;
             const dz = currentPoint.z - startPoint.z;
             const len = Math.sqrt(dx*dx + dz*dz);
             if (len < 0.01) return [startPoint, currentPoint];
             const nx = -dz / len;
             const nz = dx / len;
             const ox = nx * (thickness / 2);
             const oz = nz * (thickness / 2);
             return [
               { x: startPoint.x + ox, y: 0, z: startPoint.z + oz },
               { x: currentPoint.x + ox, y: 0, z: currentPoint.z + oz },
               { x: currentPoint.x - ox, y: 0, z: currentPoint.z - oz },
               { x: startPoint.x - ox, y: 0, z: startPoint.z - oz },
               { x: startPoint.x + ox, y: 0, z: startPoint.z + oz },
             ];
         }
         if (tool === ToolType.DRAW_RECT) {
             return [
                 startPoint,
                 { x: currentPoint.x, y: 0, z: startPoint.z },
                 currentPoint,
                 { x: startPoint.x, y: 0, z: currentPoint.z },
                 startPoint
             ];
         }
         if (tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC) {
             const dist = Math.sqrt(Math.pow(currentPoint.x - startPoint.x, 2) + Math.pow(currentPoint.z - startPoint.z, 2));
             const func = tool === ToolType.DRAW_CIRCLE ? createCirclePoints : createArcPoints;
             const seg = tool === ToolType.DRAW_CIRCLE ? 64 : 32;
             return func(dist, seg).map(p => ({
                 x: p.x + startPoint.x,
                 y: 0,
                 z: p.z + startPoint.z
             }));
         }
     }
     return [];
  }, [tool, startPoint, currentPoint, polyPoints, wallThickness]);

  const drawY = useMemo(() => {
    if (startPoint) return startPoint.y;
    if (polyPoints.length > 0) return polyPoints[0].y;
    if (currentPoint) return currentPoint.y;
    return 0;
  }, [startPoint, polyPoints, currentPoint]);

  // Determine Tooltip Text
  const getTooltipText = () => {
      if (tool === ToolType.MEASURE && measureStart && currentPoint) {
        const dist = Math.sqrt(
            Math.pow(currentPoint.x - measureStart.x, 2) + 
            Math.pow(currentPoint.z - measureStart.z, 2) +
            Math.pow(currentPoint.y - measureStart.y, 2)
        );
        return `距離: ${formatValue(dist)}`;
      }

      if (snapType === 'vertex') return "端點";
      if (snapType === 'midpoint') return "中點";
      if (snapType === 'edge') return "在邊線上";
      if (snapType === 'align') return "對齊";

      return "";
  };

  const tooltipText = getTooltipText();

  return (
    <>
      <mesh 
        name="ground_plane"
        rotation={[-Math.PI / 2, 0, 0]} 
        position={[0, -0.01, 0]} 
        onClick={handleClick}
      >
        <planeGeometry args={[100, 100]} />
        <meshBasicMaterial color="black" transparent opacity={0} />
      </mesh>

      {/* Main Cursor Ring */}
      {currentPoint && tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && (
        <group position={[currentPoint.x, currentPoint.y + 0.05, currentPoint.z]}>
            {/* Standard Cursor Helper */}
            {snapType === 'grid' || snapType === 'none' ? (
                <mesh rotation={[-Math.PI / 2, 0, 0]}>
                    <ringGeometry args={[0.1, 0.15, 32]} />
                    <meshBasicMaterial color="#ef4444" depthTest={false} />
                </mesh>
            ) : null}

            {/* Snap Indicator (Vertex/Edge/Midpoint/Align) */}
            <SnapIndicator position={new THREE.Vector3(0,0,0)} type={snapType} />
        </group>
      )}

      {/* Alignment Guides */}
      {guides.map((pts, i) => (
         <Line 
            key={`guide-${i}`} 
            points={pts.map(p => [p.x, p.y + 0.06, p.z] as [number, number, number])} 
            color="#a855f7" 
            lineWidth={2} 
            dashed 
            dashScale={10} 
            depthTest={false}
         />
      ))}

      {/* Measure Tool Rendering */}
      {tool === ToolType.MEASURE && measureStart && (
        <>
            <Line 
                points={[
                    [measureStart.x, measureStart.y + 0.05, measureStart.z],
                    (() => {
                        const target = measureEnd || currentPoint || measureStart;
                        return [target.x, target.y + 0.05, target.z] as [number, number, number];
                    })()
                ]} 
                color="#facc15" 
                lineWidth={2} 
                dashed 
                dashScale={50}
                depthTest={false}
            />
             <mesh position={[measureStart.x, measureStart.y, measureStart.z]}>
                <sphereGeometry args={[0.08]} />
                <meshBasicMaterial color="#facc15" depthTest={false} />
            </mesh>
            {(measureEnd || currentPoint) && (
                <mesh position={(() => {
                    const p = measureEnd || currentPoint;
                    return p ? [p.x, p.y, p.z] : [0,0,0];
                })()}>
                    <sphereGeometry args={[0.08]} />
                    <meshBasicMaterial color="#facc15" depthTest={false} />
                </mesh>
            )}
        </>
      )}

      {/* Global Cursor/Snap Tooltip */}
      {currentPoint && tooltipText && (
          <CursorTooltip 
            position={[currentPoint.x, currentPoint.y + 0.5, currentPoint.z]}
            text={tooltipText}
            type={snapType}
          />
      )}

      {/* Drawing Preview Fill */}
      {previewPoints.length > 0 && (startPoint || polyPoints.length > 0) && (
         <PreviewFill points={previewPoints} y={drawY} />
      )}

      {/* Drawing Preview Outline */}
      {previewPoints.length > 1 && (
        <Line 
           name="preview_helper"
           points={previewPoints.map(p => [p.x, drawY + 0.06, p.z] as [number, number, number])}
           color="#38bdf8"
           lineWidth={2}
           transparent
           opacity={0.8}
        />
      )}
    </>
  );
};

// --- Push/Pull Handle Component ---
const PushPullHandle: React.FC<{
  position: THREE.Vector3;
  rotation: THREE.Euler;
  axis: 'x' | 'y' | 'z';
  color: string;
  onDragStart: () => void;
  onDrag: (e: any) => void;
  onDragEnd: () => void;
  label: string;
}> = ({ position, rotation, axis, color, onDragStart, onDrag, onDragEnd, label }) => {
  return (
    <TransformControls
      mode="translate"
      position={[position.x, position.y, position.z]}
      rotation={[rotation.x, rotation.y, rotation.z]}
      showX={axis === 'x'}
      showY={axis === 'y'}
      showZ={axis === 'z'}
      onMouseDown={onDragStart}
      onObjectChange={onDrag}
      onMouseUp={onDragEnd}
      translationSnap={0.05}
    >
      <mesh>
         <boxGeometry args={[0.2, 0.2, 0.2]} />
         <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.8} />
      </mesh>
      <Html position={[axis === 'x' ? 0.3 : 0, axis === 'y' ? 0.3 : 0, axis === 'z' ? 0.3 : 0]} center style={{ pointerEvents: 'none' }}>
         <div className="text-white text-[10px] px-1 rounded font-mono shadow-md whitespace-nowrap" style={{ backgroundColor: color }}>
             {label}
         </div>
      </Html>
    </TransformControls>
  );
};

const RenderedShape: React.FC<{ shape: IShape }> = ({ shape }) => {
  const { selectedId, setSelectedId, tool, updateShape, formatValue } = useApp();
  const isSelected = selectedId === shape.id;
  const groupRef = useRef<THREE.Group>(null);

  // Drag State Ref to avoid closure staleness and re-renders during drag
  const dragState = useRef<{
     fixedPoint: THREE.Vector3;
     baseSize: number;
     initialScale: number;
     initialPos: THREE.Vector3;
     rotation: number;
     worldDirection: THREE.Vector3;
  } | null>(null);

  const threeShape = useMemo(() => {
    if (shape.type === 'dimension') return null;
    return createThreeShape(shape.points);
  }, [shape.points, shape.type]);

  const baseDimensions = useMemo(() => getBaseDimensions(shape.points), [shape.points]);

  const geometry = useMemo(() => {
    if (!threeShape || shape.type === 'dimension') return null;
    return new THREE.ExtrudeGeometry(threeShape, { depth: shape.height, bevelEnabled: false });
  }, [threeShape, shape.height, shape.type]);

  // Sync ref with props (React State) when not dragging
  useEffect(() => {
    if (groupRef.current && !dragState.current) {
        groupRef.current.position.set(shape.position[0], shape.position[1], shape.position[2]);
        groupRef.current.rotation.set(0, shape.rotation, 0); 
        groupRef.current.scale.set(shape.scale[0], shape.scale[1], shape.scale[2]);
    }
  }, [shape.position, shape.rotation, shape.scale]);

  // Standard Select Tool (Move/Rotate)
  const handleTransformChange = (e: any) => {
      if (!groupRef.current) return;
      updateShape(shape.id, {
        position: [groupRef.current.position.x, groupRef.current.position.y, groupRef.current.position.z],
        rotation: groupRef.current.rotation.y,
        scale: [groupRef.current.scale.x, groupRef.current.scale.y, groupRef.current.scale.z]
      });
  };

  // --- Push/Pull Handlers ---
  const { maxX, maxZ, width: baseWidth, depth: baseDepth } = baseDimensions;
  // Dimensions accounting for scale
  const currentW = baseWidth * shape.scale[0];
  const currentD = baseDepth * shape.scale[2];
  const currentH = shape.height * shape.scale[1]; // usually scale[1] is 1, but just in case

  // Helpers to start drag
  const setupDrag = (face: 'right' | 'left' | 'front' | 'back') => {
      if (!groupRef.current) return;

      const rot = shape.rotation;
      const pos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
      const right = new THREE.Vector3(1, 0, 0).applyAxisAngle(new THREE.Vector3(0, 1, 0), rot);
      const forward = new THREE.Vector3(0, 0, 1).applyAxisAngle(new THREE.Vector3(0, 1, 0), rot);

      let fixedPoint = pos.clone();
      let worldDirection = right.clone();
      let baseSize = baseWidth;
      let initialScale = shape.scale[0];

      if (face === 'right') {
          // Fix Left edge: Pos - Right * (W/2)
          fixedPoint.sub(right.clone().multiplyScalar(currentW / 2));
          worldDirection = right;
          baseSize = baseWidth;
          initialScale = shape.scale[0];
      } else if (face === 'left') {
          // Fix Right edge: Pos + Right * (W/2)
          fixedPoint.add(right.clone().multiplyScalar(currentW / 2));
          // Direction is Negative Right (Left)
          worldDirection = right.clone().negate();
          baseSize = baseWidth;
          initialScale = shape.scale[0];
      } else if (face === 'front') {
          // Fix Back edge: Pos - Forward * (D/2)
          fixedPoint.sub(forward.clone().multiplyScalar(currentD / 2));
          worldDirection = forward;
          baseSize = baseDepth;
          initialScale = shape.scale[2];
      } else if (face === 'back') {
          // Fix Front edge: Pos + Forward * (D/2)
          fixedPoint.add(forward.clone().multiplyScalar(currentD / 2));
          worldDirection = forward.clone().negate();
          baseSize = baseDepth;
          initialScale = shape.scale[2];
      }

      dragState.current = {
          fixedPoint,
          worldDirection,
          baseSize,
          initialScale,
          initialPos: pos,
          rotation: rot
      };
  };

  const handleDrag = (e: any, face: 'right' | 'left' | 'front' | 'back') => {
     if (!groupRef.current || !dragState.current || !e.target.object) return;
     const handlePos = e.target.object.position.clone();
     const { fixedPoint, worldDirection, baseSize } = dragState.current;

     // Vector from Fixed Point to Handle
     const dragVec = handlePos.sub(fixedPoint);

     // Project onto expansion direction
     // New Length is the distance along the normal from fixed edge
     let newLen = dragVec.dot(worldDirection);
     if (newLen < 0.1) newLen = 0.1;

     const newScale = newLen / baseSize;

     // Calculate New Center: FixedPoint + Direction * (NewLen / 2)
     const centerOffset = worldDirection.clone().multiplyScalar(newLen / 2);
     const newCenter = fixedPoint.clone().add(centerOffset);

     // Apply to Object
     groupRef.current.position.copy(newCenter);

     if (face === 'right' || face === 'left') {
         groupRef.current.scale.setX(newScale);
     } else {
         groupRef.current.scale.setZ(newScale);
     }
  };

  const handleDragEnd = () => {
      if (!groupRef.current) return;
      // Commit
      updateShape(shape.id, {
          position: [groupRef.current.position.x, groupRef.current.position.y, groupRef.current.position.z],
          scale: [groupRef.current.scale.x, groupRef.current.scale.y, groupRef.current.scale.z]
      });
      dragState.current = null;
  };

  // Height is simpler (scales from bottom)
  const onHeightDrag = (e: any) => {
    if (!groupRef.current || !e.target.object) return;
    const currentY = e.target.object.position.y;
    const newScaleY = Math.max(0.01, currentY / shape.height);
    groupRef.current.scale.y = newScaleY;
  };

  const onHeightEnd = (e: any) => {
    if (!groupRef.current || !e.target.object) return;
    const currentY = e.target.object.position.y;
    const newHeight = Math.max(0.01, currentY);
    updateShape(shape.id, { 
       height: newHeight,
       scale: [shape.scale[0], 1, shape.scale[2]], 
       type: newHeight > 0.1 ? 'solid' : 'flat'
    });
    groupRef.current.scale.y = 1;
  };


  if (shape.type === 'dimension') {
      const p1 = shape.points[0];
      const p2 = shape.points[1];
      const dist = Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.z - p1.z, 2) + Math.pow(p2.y - p1.y, 2));
      const midX = (p1.x + p2.x) / 2;
      const midY = (p1.y + p2.y) / 2 + 0.1;
      const midZ = (p1.z + p2.z) / 2;
      return (
        <group 
            ref={groupRef}
            userData={{ isShape: true, id: shape.id }}
            onClick={(e) => {
                if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
                    e.stopPropagation();
                    setSelectedId(shape.id);
                }
            }}
        >
            <Line points={[[p1.x, p1.y+0.05, p1.z], [p2.x, p2.y+0.05, p2.z]]} color={isSelected ? HIGHLIGHT_COLOR : shape.color} lineWidth={3} dashed dashScale={10} />
            <mesh position={[p1.x, p1.y+0.05, p1.z]}><sphereGeometry args={[0.06]} /><meshBasicMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} /></mesh>
            <mesh position={[p2.x, p2.y+0.05, p2.z]}><sphereGeometry args={[0.06]} /><meshBasicMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} /></mesh>
            <Html position={[midX, midY, midZ]} center style={{ pointerEvents: 'none' }}>
                <div className={`text-xs px-2 py-1 rounded whitespace-nowrap backdrop-blur-sm border ${isSelected ? 'bg-blue-600/90 text-white border-blue-400' : 'bg-black/70 text-yellow-400 border-yellow-500/50'}`}>
                    {formatValue(dist)}
                </div>
            </Html>
        </group>
      );
  }

  // Calculate Handle Positions
  const rot = shape.rotation;
  const sin = Math.sin(rot);
  const cos = Math.cos(rot);
  // Center is shape.position
  const cx = shape.position[0];
  const cy = shape.position[1];
  const cz = shape.position[2];

  // Offsets relative to center (unrotated)
  const hw = currentW / 2; // half width
  const hd = currentD / 2; // half depth
  const hh = currentH;     // full height (y starts at 0)

  // Rotate offsets
  // X axis (Right): (hw, 0, 0) -> (hw*cos, 0, hw*sin)
  // Z axis (Front): (0, 0, hd) -> (-hd*sin, 0, hd*cos)

  // Right Handle
  const posRight = new THREE.Vector3(cx + hw * cos, cy + hh / 2, cz + hw * sin);
  // Left Handle
  const posLeft = new THREE.Vector3(cx - hw * cos, cy + hh / 2, cz - hw * sin);
  // Front Handle (Z+)
  const posFront = new THREE.Vector3(cx - hd * sin, cy + hh / 2, cz + hd * cos);
  // Back Handle (Z-)
  const posBack = new THREE.Vector3(cx + hd * sin, cy + hh / 2, cz - hd * cos);
  // Top Handle
  const posTop = new THREE.Vector3(cx, cy + hh, cz);

  const euler = new THREE.Euler(0, rot, 0);

  return (
    <>
      {/* --- Standard Move/Rotate Controls (Only in SELECT mode) --- */}
      {isSelected && tool === ToolType.SELECT && (
        <TransformControls
            object={groupRef}
            mode="translate"
            showY={true} showX={true} showZ={true}
            onMouseUp={handleTransformChange}
        />
      )}

      {/* --- Push/Pull Resize Controls (5 Independent Handles) --- */}
      {isSelected && tool === ToolType.PUSH_PULL && (
        <>
            {/* Top (Height) */}
            <PushPullHandle 
                position={posTop} rotation={euler} axis="y" color="#4ade80" label="高"
                onDragStart={() => {}} 
                onDrag={onHeightDrag} 
                onDragEnd={onHeightEnd} 
            />
            {/* Right (+X) */}
            <PushPullHandle 
                position={posRight} rotation={euler} axis="x" color="#f87171" label="右"
                onDragStart={() => setupDrag('right')} 
                onDrag={(e) => handleDrag(e, 'right')} 
                onDragEnd={handleDragEnd} 
            />
            {/* Left (-X) */}
            <PushPullHandle 
                position={posLeft} rotation={euler} axis="x" color="#f87171" label="左"
                onDragStart={() => setupDrag('left')} 
                onDrag={(e) => handleDrag(e, 'left')} 
                onDragEnd={handleDragEnd} 
            />
             {/* Front (+Z) */}
             <PushPullHandle 
                position={posFront} rotation={euler} axis="z" color="#60a5fa" label="前"
                onDragStart={() => setupDrag('front')} 
                onDrag={(e) => handleDrag(e, 'front')} 
                onDragEnd={handleDragEnd} 
            />
             {/* Back (-Z) */}
             <PushPullHandle 
                position={posBack} rotation={euler} axis="z" color="#60a5fa" label="後"
                onDragStart={() => setupDrag('back')} 
                onDrag={(e) => handleDrag(e, 'back')} 
                onDragEnd={handleDragEnd} 
            />
        </>
      )}

      <group 
        ref={groupRef}
        userData={{ isShape: true, id: shape.id }}
        onClick={(e) => {
          if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
            e.stopPropagation();
            setSelectedId(shape.id);
          }
        }}
      >
        <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <primitive object={geometry} attach="geometry" />
            <meshStandardMaterial 
              color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
              transparent={isSelected || shape.type === 'flat'} 
              opacity={shape.type === 'flat' ? 0.6 : (isSelected ? 0.9 : 1)}
              side={THREE.DoubleSide}
            />
            {isSelected && (
              <lineSegments>
                <edgesGeometry args={[geometry]} />
                <lineBasicMaterial color="white" />
              </lineSegments>
            )}
        </mesh>
      </group>
    </>
  );
};

